            return [step_toward(sx, target[0]), step_toward(sy, target[1])]
        return [step_toward(ox, sx), step_toward(oy, sy)]

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        best = None
        best_d = None
        for t in targets:
            p = as_pair(t)
            if p is None:
                continue
            d = manhattan(p, [sx, sy])
            if best is None or d < best_d:
                best = p
                best_d = d
        if best is not None:
            return [step_toward(sx, best[0]), step_toward(sy, best[1])]
        return [step_toward(sx, ox), step_toward(sy, oy)]

    resources = observation.get("resources") or observation.get("resource_cells") or []
    best = None
    best_d = None
    for r in resources:
        p = as_pair(r)
        if p is None:
            continue
        d = manhattan(p, [sx, sy])
        if best is None or d < best_d:
            best = p
            best_d = d
    if best is not None:
        return [step_toward(sx, best[0]), step_toward(sy, best[1])]

    return [step_toward(sx, ox), step_toward(sy, oy)]

